class Solution {
public:
    vector<int> missingRolls(vector<int>& rolls,int mean,int n){
        int total=mean*(n+(int)rolls.size());
        for(int x:rolls)total-=x;
        if(total<n||total>6*n)return {};
        vector<int>ans(n,total/n);int rem=total%n;
        for(int i=0;i<rem;++i)++ans[i];return ans;
    }
};
